// Package: AWSSDK.SimpleNotificationService
using Amazon.SimpleNotificationation;
using Amazon.SimpleNotificationation.Model;

var snsClient = new AmazonSimpleNotificationServiceClient(RegionEndpoint.USEast1);

var createTopicRequest = new CreateTopicRequest
{
    Name = "aspnet-order-events"
};
var createTopicResponse = await snsClient.CreateTopicAsync(createTopicRequest);
string topicArn = createTopicResponse.TopicArn;
Console.WriteLine($"Topic ARN: {topicArn}");

var publishRequest = new PublishRequest
{
    TopicArn = topicArn,
    Subject = "New Order Received",
    Message = "Order 1001 placed by customer 42."
};

var publishResponse = await snsClient.PublishAsync(publishRequest);
Console.WriteLine($"MessageId: {publishResponse.MessageId}");

var emailSubscribeRequest = new SubscribeRequest
{
    TopicArn = topicArn,
    Protocol = "email",
    Endpoint = "ops@example.com"
};
await snsClient.SubscribeAsync(emailSubscribeRequest);

var sqsSubscribeRequest = new SubscribeRequest
{
    TopicArn = topicArn,
    Protocol = "sqs",
    Endpoint = "arn:aws:sqs:us-east-1:123456789012:aspnet-notifications-queue"
};
await snsClient.SubscribeAsync(sqsSubscribeRequest);

// SNS sends a confirmation to the email; the recipient must confirm before delivery.
